import java.util.*;

class Solution {
  public int minOperations(String s1, String s2, int x) {
    List<Integer> mismatch = new ArrayList<>();
    for (int i = 0; i < s1.length(); i++) if (s1.charAt(i) != s2.charAt(i)) mismatch.add(i);
    int m = mismatch.size();
    if ((m & 1) != 0) return -1;
    long[] dp = new long[m + 1];
    Arrays.fill(dp, Long.MAX_VALUE / 4);
    dp[0] = 0;
    if (m > 0) dp[1] = x;
    for (int i = 0; i + 1 < m; i++) {
      dp[i + 2] =
          Math.min(
              dp[i + 2], dp[i] + Math.min(2L * x, 2L * (mismatch.get(i + 1) - mismatch.get(i))));
      dp[i + 2] = Math.min(dp[i + 2], dp[i + 1] + x);
    }
    return (int) (dp[m] / 2);
  }
}
